package team.rustcraft.building;
import net.minecraft.block.BlockState;import net.minecraft.item.*;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.sound.SoundCategory;import net.minecraft.sound.SoundEvents;import net.minecraft.util.*;import net.minecraft.util.math.*;import net.minecraft.world.World;import team.rustcraft.api.building.*;import team.rustcraft.api.death.WorldPosition;import team.rustcraft.api.player.PlayerId;import java.util.UUID;
public final class BuildingPlanItem extends Item { public BuildingPlanItem(Settings settings){super(settings);} @Override public ActionResult useOnBlock(ItemUsageContext ctx){ World w=ctx.getWorld(); if(w.isClient) return ActionResult.SUCCESS; ServerPlayerEntity p=(ServerPlayerEntity)ctx.getPlayer(); if(p==null) return ActionResult.PASS; BlockPos origin=ctx.getBlockPos().offset(ctx.getSide()); String world=w.getRegistryKey().getValue().toString(); WorldPosition wp=new WorldPosition(world,origin.getX(),origin.getY(),origin.getZ()); BuildingPlacementValidator v=new BuildingPlacementValidator(RustCraftBuildingMod.BUILDINGS,RustCraftBuildingMod.CONFIG); BuildingPlacementValidator.Result r=v.validateFoundation(new PlayerId(p.getUuid()),wp,new BuildingPlacementValidator.WorldAccess(){public boolean isAir(WorldPosition pos){return w.getBlockState(new BlockPos(pos.x(),pos.y(),pos.z())).isAir();} public boolean isSolid(WorldPosition pos){return w.getBlockState(new BlockPos(pos.x(),pos.y(),pos.z())).isSideSolidFullSquare(w,new BlockPos(pos.x(),pos.y(),pos.z()),Direction.UP);}}); if(!r.valid()){p.sendMessage(net.minecraft.text.Text.literal("Cannot place foundation: "+r.reason()),true); return ActionResult.FAIL;} BuildingId bid=new BuildingId("building-"+UUID.randomUUID()); RustCraftBuildingMod.BUILDINGS.createBuilding(bid,new PlayerId(p.getUuid())); BuildingBlockId bbid=new BuildingBlockId("block-"+UUID.randomUUID()); RustCraftBuildingMod.BUILDINGS.addBlock(bbid,bid,BuildingBlockType.FOUNDATION,BuildingGrade.TWIG,RustCraftBuildingMod.maxHealth(BuildingGrade.TWIG),wp); BlockState state=RustCraftBuildingMod.TWIG_FOUNDATION.getDefaultState(); for(WorldPosition fp: BuildingPlacementValidator.footprint(wp)){BlockPos bp=new BlockPos(fp.x(),fp.y(),fp.z()); w.setBlockState(bp,state); RustCraftBuildingMod.INDEX.putBlock(world,bp,bbid);} w.playSound(null,origin,SoundEvents.BLOCK_WOOD_PLACE,SoundCategory.BLOCKS,1,1); return ActionResult.CONSUME; }}
